export const blankIds=prompt=>[...String(prompt).matchAll(/\{\{(\d+)\}\}/g)].map(x=>Number(x[1]));
export function validateQuestionExtras(q){if(q.code!==undefined&&(typeof q.code!=='string'||q.code.length>20000))return false;if(q.language!==undefined&&(typeof q.language!=='string'||q.language.length>40))return false;if(q.responseFormat!==undefined&&(!['text','code'].includes(q.responseFormat)||q.type!=='open'))return false;if(q.type==='multiple'){return Array.isArray(q.options)&&q.options.length>=2&&q.options.length<=6&&q.options.every(x=>typeof x==='string'&&x.trim()&&x.length<=2000)&&Array.isArray(q.corrects)&&q.corrects.length>=2&&new Set(q.corrects).size===q.corrects.length&&q.corrects.every(n=>Number.isInteger(n)&&n>=0&&n<q.options.length)&&!('correct'in q);}if(q.type!=='blanks')return true;const ids=blankIds(q.prompt);if(!Array.isArray(q.blanks)||q.blanks.length<1||q.blanks.length>20||ids.length!==q.blanks.length||ids.some((n,i)=>n!==i+1)||typeof q.ignoreCase!=='boolean'||typeof q.ignoreAccents!=='boolean')return false;return q.blanks.every(b=>b&&Array.isArray(b.accepted)&&b.accepted.length>=1&&b.accepted.length<=10&&b.accepted.every(s=>typeof s==='string'&&s.trim()&&s.length<=100));}
export function normalizedBlank(s,q){let v=String(s).normalize('NFKC').trim().replace(/\s+/g,' ');if(q.ignoreCase)v=v.toLocaleLowerCase('pt-BR');if(q.ignoreAccents)v=v.normalize('NFD').replace(/[\u0300-\u036f]/g,'');return v;}
export function blankResults(q,value){return(q.blanks||[]).map((b,i)=>typeof value?.[i]==='string'&&!!value[i].trim()&&(b.accepted||[]).some(s=>normalizedBlank(value[i],q)===normalizedBlank(s,q)));}
export function automaticPoints(q,value){if(q.type==='choice')return value===q.correct?q.points:0;if(q.type==='multiple')return multipleBreakdown(q,value).earned;if(q.type==='blanks'){const results=blankResults(q,value);return results.length?q.points*results.filter(Boolean).length/results.length:0;}return 0;}
export function validBlankAnswer(q,value,complete){return Array.isArray(value)&&value.length===q.blanks.length&&Array.from(value).every(s=>typeof s==='string'&&s.length<=100&&(!complete||!!s.trim()));}
export function validMultipleAnswer(q,value){return Array.isArray(value)&&value.length<=q.options.length&&new Set(value).size===value.length&&Array.from(value).every(n=>Number.isInteger(n)&&n>=0&&n<q.options.length);}
export function multipleBreakdown(q,value){const marked=new Set(Array.isArray(value)?value:[]),correct=new Set(q.corrects||[]);const missed=[...correct].filter(n=>!marked.has(n)).length,wrong=[...marked].filter(n=>!correct.has(n)).length;return{missed,wrong,unit:q.points/Math.max(1,correct.size),earned:Math.max(0,q.points-(missed+wrong)*q.points/Math.max(1,correct.size))};}
